{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 시장이 3,000㎡ 이상 대형건축물에 자전거 대여소를 설치·운영할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제11조제3항에 따르면 시장은 3,000㎡ 이상 대형건축물 등 자전거의 이용수요가 많은 장소에 자전거대여소를 설치·운영할 수 있다. 따라서 면적이 정확히 3,000㎡인 건물은 ‘3,000㎡ 이상 대형건축물’에 해당하므로, 자전거 이용수요가 많은 경우 시장이 자전거 대여소를 설치·운영할 수 있다.",
          "b_ids": "자전거:제11조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
